package com.bank.reverse;

import java.util.logging.*;

public class ReverseDemo {
    private static final Logger log = Logger.getLogger("Reverse");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        ReverseService service = new ReverseService();
        log.info(() -> "direct : " + service.reverse("SAV2001"));
        log.info(() -> "stream : " + service.reverseWithStream("SAV2001"));
    }
}

// ─── Would be in service/ReverseService.java ───
class ReverseService {
    // idiomatic, Unicode-safe, efficient
    String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }

    // stream variant: collect chars into StringBuilder, then reverse
    String reverseWithStream(String s) {
        return s.chars()
            .mapToObj(c -> (char) c)
            .collect(StringBuilder::new, StringBuilder::append, StringBuilder::append)
            .reverse()
            .toString();
    }
}
